import math
pts=[]
t0=None
lastlog=-99
def clamp(x,a,b):return max(a,min(b,x))
def median(a):
 a=sorted(a);return a[len(a)//2]
def control(o):
 global pts,t0,lastlog
 t=o['t'];dt=o['dt']
 if t0 is None:t0=t
 v=o['motion']['v_mps'];delta=math.radians(o['steer_deg']);yaw=v*math.tan(delta)/2.5*dt
 c=math.cos(yaw);s=math.sin(yaw)
 pts=[(c*(x-v*dt)+s*y,-s*(x-v*dt)+c*y,age+dt) for x,y,age in pts if age<8]
 for name,view in o['views'].items():
  if name=='periphery':continue
  ox,oy=view['origin']
  for b,d in view['walls']:
   b=math.radians(b);x=ox+d*math.cos(b);y=oy+d*math.sin(b)
   if -23<x<4:pts.append((x,y,0))
 if len(pts)>2400:pts=pts[::2]
 h=math.radians(o['hitch_deg']);ch=math.cos(h);sh=math.sin(h)
 rx,ry=o['rig']['trailer_rear']
 rails=[]
 for x,y,age in pts:
  dx=x-rx;dy=y-ry
  r=-ch*dx+sh*dy;q=sh*dx+ch*dy
  if -3<r<12:rails.append((r,q,age))
 centers=[]
 for r0 in [1,2,3,4,5,6,7]:
  left=[q for r,q,a in rails if abs(r-r0)<0.85 and 0.8<q<7]
  right=[q for r,q,a in rails if abs(r-r0)<0.85 and -7<q<-0.8]
  if len(left)>2 and len(right)>2:
   l=median(left);r=median(right)
   if 3<l-r<8:centers.append((r0,(l+r)/2))
 look=64.3 if int((t-t0)/2)%2 else -64.3
 desired=0.0;valid=False
 if centers:
  r,q=min(centers,key=lambda z:abs(z[0]-4.5))
  desired=math.degrees(math.atan(4.9*2*q/(r*r+q*q)))
  desired=clamp(desired,-26,26);valid=True
 steer=math.degrees(math.atan(2.5*math.sin(h)/(3.6+1.3*math.cos(h))))+1.8*(o['hitch_deg']-desired)
 speed=-0.65 if valid else -0.25
 if abs(o['hitch_deg'])>34:speed=0;wake('Hitch needs review')
 if t-lastlog>5:
  print({'t':t,'p':o['progress']['covered'],'h':o['hitch_deg'],'desired':round(desired,1),'centers':[(r,round(q,2)) for r,q in centers]});lastlog=t
 return (clamp(steer,-40,40),speed,look)

